def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_ids = None

        for mask in range(1 << len(jobs)):
            if mask.bit_count() != k:
                continue
            chosen = [jobs[i] for i in range(len(jobs)) if mask >> i & 1]
            ids = {job["id"] for job in chosen}
            if ids & blocked or not mandatory.issubset(ids):
                continue

            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            feasible = True
            for job in chosen:
                overlap = sum(other["start"] <= job["start"] < other["end"]
                              for other in chosen)
                if overlap > capacity:
                    feasible = False
                    break
            if not feasible:
                continue

            selected = sorted(ids)
            value = sum(job["value"] for job in chosen)
            if (best is None or value > best or
                    (value == best and
                     (selected < best_ids if tie == "smallest" else selected > best_ids))):
                best, best_ids = value, selected

        if best is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best}
    return solve


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]

    domains = []
    for name in names:
        forbidden = set(blocked.get(name, []))
        pin = pins.get(name)
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in forbidden and
                          (pin is None or row["version"] == pin))
        domains.append([None] + versions)

    best_vector = None
    best_installation = None
    for values in product(*domains):
        chosen = {name: version for name, version in zip(names, values)
                  if version is not None}
        rows = {name: next(row for row in packages[name]
                           if row["version"] == version)
                for name, version in chosen.items()}

        if any(name not in chosen or not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        edges = {name: [] for name in chosen}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in chosen or not dep["min"] <= chosen[target] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        pending = list(roots)
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            if name not in chosen:
                valid = False
                break
            reachable.add(name)
            pending.extend(edges[name])
        if not valid or reachable != set(chosen):
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(target) for target in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in chosen):
            continue

        vector = tuple(chosen.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_installation = chosen

    if best_vector is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_installation}


def _routes(data):
    import heapq

    required = data.get("required", [])
    required_bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start = data["source"]
    initial_mask = required_bit.get(start, 0)
    coupons = data["coupons"]
    initial = (start, coupons, initial_mask)
    distances = {initial: data["start"]}
    queue = [(data["start"], start, coupons, initial_mask)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                remaining - 1))
            next_mask = mask | required_bit.get(edge["v"], 0)
            for duration, next_remaining in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (edge["v"], next_remaining, next_mask)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, edge["v"],
                                           next_remaining, next_mask))
    return {"arrival": None}


